};

C3DVector CMatrix3x4::operator*(const C3DVector& v) const
{
    C3DVector result;
    result.X = m_row0.X * v.X + m_row0.Y * v.Y + m_row0.Z * v.Z;
    result.Y = m_row1.X * v.X + m_row1.Y * v.Y + m_row1.Z * v.Z;
    result.Z = m_row2.X * v.X + m_row2.Y * v.Y + m_row2.Z * v.Z;
    return result;
}

